1. @page "/book-appointment"
2. @rendermode InteractiveServer
3. @using sv_6a74d58999dc484598c2a6eddd5b3932.Services
4. @inject AppointmentService AppointmentService
5. 
6. <PageTitle>Book Appointment</PageTitle>
7. 
8. <h1>Book an Appointment</h1>
9. 
10. <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
11.     <DataAnnotationsValidator />
12. 
13.     <h3>Step 1: Patient Information</h3>
14. 
15.     <div class="mb-3">
16.         <label class="form-label" for="patientName">Patient Name</label>
17.         <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
18.         <ValidationMessage For="() => Model.PatientName" />
19.     </div>
20. 
21.     <div class="mb-3">
22.         <label class="form-label" for="email">Email</label>
23.         <InputText id="email" class="form-control" @bind-Value="Model.Email" />
24.         <ValidationMessage For="() => Model.Email" />
25.         @if (serverErrors.ContainsKey("Email"))
26.         {
27.             <div class="validation-message">@serverErrors["Email"]</div>
28.         }
29.     </div>
30. 
31.     <div class="mb-3">
32.         <label class="form-label" for="phone">Phone</label>
33.         <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
34.         <ValidationMessage For="() => Model.Phone" />
35.     </div>
36. 
37.     <div class="mb-3">
38.         <label class="form-label" for="insurance">Insurance Provider</label>
39.         <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
40.             <option value="">-- Select --</option>
41.             <option value="Aetna">Aetna</option>
42.             <option value="BlueCross">BlueCross</option>
43.             <option value="Cigna">Cigna</option>
44.             <option value="UnitedHealth">UnitedHealth</option>
45.             <option value="None">None</option>
46.         </InputSelect>
47.         <ValidationMessage For="() => Model.InsuranceProvider" />
48.     </div>
49. 
50.     @if (showStep2)
51.     {
52.         <h3>Step 2: Appointment Details</h3>
53. 
54.         <div class="mb-3">
55.             <label class="form-label" for="doctor">Preferred Doctor</label>
56.             <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorChanged">
57.                 <option value="">-- Select --</option>
58.                 @foreach (var doc in doctors)
59.                 {
60.                     <option value="@doc">@doc</option>
61.                 }
62.             </InputSelect>
63.             <ValidationMessage For="() => Model.Doctor" />
64.             @if (serverErrors.ContainsKey("Doctor"))
65.             {
66.                 <div class="validation-message">@serverErrors["Doctor"]</div>
67.             }
68.         </div>
69. 
70.         <div class="mb-3">
71.             <label class="form-label" for="date">Date</label>
72.             <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDateChanged" />
73.             <ValidationMessage For="() => Model.AppointmentDate" />
74.         </div>
75. 
76.         <div class="mb-3">
77.             <label class="form-label" for="timeslot">Time Slot</label>
78.             <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
79.                 <option value="">-- Select --</option>
80.                 @foreach (var slot in timeSlots)
81.                 {
82.                     <option value="@slot">@slot</option>
83.                 }
84.             </InputSelect>
85.             <ValidationMessage For="() => Model.TimeSlot" />
86.             @if (serverErrors.ContainsKey("TimeSlot"))
87.             {
88.                 <div class="validation-message">@serverErrors["TimeSlot"]</div>
89.             }
90.         </div>
91. 
92.         <div class="mb-3">
93.             <label class="form-label" for="reason">Reason for Visit</label>
94.             <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="4" />
95.             <ValidationMessage For="() => Model.ReasonForVisit" />
96.         </div>
97. 
98.         <button type="submit" class="btn btn-primary">Book Appointment</button>
99.     }
100. </EditForm>
101. 
102. @if (!showStep2)
103. {
104.     <button class="btn btn-secondary mt-3" @onclick="CheckAvailability">Check Availability</button>
105. }
106. 
107. @if (appointmentConfirmed)
108. {
109.     <div class="alert alert-success mt-3">
110.         Appointment booked successfully!
111.     </div>
112. }
113. 
114. @code {
115.     private AppointmentModel Model { get; set; } = new();
116.     private bool showStep2;
117.     private bool appointmentConfirmed;
118.     private List<string> doctors = new();
119.     private List<string> timeSlots = new();
120.     private Dictionary<string, string> serverErrors = new();
121.     private EditContext? editContext;
122. 
123.     protected override void OnInitialized()
124.     {
125.         editContext = new EditContext(Model);
126.     }
127. 
128.     private async Task CheckAvailability()
129.     {
130.         serverErrors.Clear();
131. 
132.         // Validate step 1 fields manually
133.         editContext = new EditContext(Model);
134.         var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
135.         bool step1Valid = true;
136. 
137.         // Validate individual step 1 properties
138.         var step1Properties = new[] { nameof(Model.PatientName), nameof(Model.Email), nameof(Model.Phone), nameof(Model.InsuranceProvider) };
139.         foreach (var prop in step1Properties)
140.         {
141.             var propInfo = typeof(AppointmentModel).GetProperty(prop)!;
142.             var value = propInfo.GetValue(Model);
143.             var propContext = new System.ComponentModel.DataAnnotations.ValidationContext(Model) { MemberName = prop };
144.             var propResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
145.             if (!System.ComponentModel.DataAnnotations.Validator.TryValidateProperty(value, propContext, propResults))
146.             {
147.                 step1Valid = false;
148.             }
149.         }
150. 
151.         if (!step1Valid)
152.         {
153.             // Trigger full validation to show messages
154.             editContext.Validate();
155.             return;
156.         }
157. 
158.         // Load doctors and show step 2
159.         doctors = await AppointmentService.GetDoctorsAsync();
160.         showStep2 = true;
161.     }
162. 
163.     private async Task OnDoctorChanged()
164.     {
165.         serverErrors.Remove("Doctor");
166.         await LoadTimeSlots();
167.     }
168. 
169.     private async Task OnDateChanged()
170.     {
171.         await LoadTimeSlots();
172.     }
173. 
174.     private async Task LoadTimeSlots()
175.     {
176.         if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
177.         {
178.             timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate.Value);
179.         }
180.         else
181.         {
182.             timeSlots = new();
183.         }
184.         Model.TimeSlot = "";
185.         serverErrors.Remove("TimeSlot");
186.     }
187. 
188.     private async Task HandleSubmit()
189.     {
190.         serverErrors.Clear();
191.         appointmentConfirmed = false;
192. 
193.         var errors = await AppointmentService.ValidatePatientAsync(
194.             Model.Email,
195.             Model.InsuranceProvider,
196.             Model.Doctor,
197.             Model.TimeSlot);
198. 
199.         if (errors.Count > 0)
200.         {
201.             serverErrors = errors;
202.             return;
203.         }
204. 
205.         appointmentConfirmed = true;
206.     }
207. 
208.     public class AppointmentModel
209.     {
210.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required")]
211.         public string PatientName { get; set; } = "";
212. 
213.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required")]
214.         [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format")]
215.         public string Email { get; set; } = "";
216. 
217.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required")]
218.         public string Phone { get; set; } = "";
219. 
220.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required")]
221.         public string InsuranceProvider { get; set; } = "";
222. 
223.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required")]
224.         public string Doctor { get; set; } = "";
225. 
226.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required")]
227.         [FutureDate(ErrorMessage = "Date must be in the future")]
228.         public DateTime? AppointmentDate { get; set; }
229. 
230.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required")]
231.         public string TimeSlot { get; set; } = "";
232. 
233.         [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required")]
234.         [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or less")]
235.         public string ReasonForVisit { get; set; } = "";
236.     }
237. 
238.     public class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
239.     {
240.         protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(object? value, System.ComponentModel.DataAnnotations.ValidationContext validationContext)
241.         {
242.             if (value is DateTime date && date.Date <= DateTime.Today)
243.             {
244.                 return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
245.             }
246.             return System.ComponentModel.DataAnnotations.ValidationResult.Success;
247.         }
248.     }
249. }
250.

